/**************TEST CLASS DECLARATION*************/
 class ArticleFavoriteApiTest extends ApiTestBase {}
/**************TEST SETUP BEGIN*************/
@BeforeEach
void setUpRestAssured(){
    RestAssured.port = port;
    RestAssured.enableLoggingOfRequestAndResponseIfValidationFails();
  }
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
void favoriteArticle_authenticated_returns200WithFavoritedTrue(){
    String uid = uid();
    String token = registerAndGetToken(uid);
    String slug = createArticleAndGetSlug(token, "Favorite Me " + uid);

    given()
        .contentType(ContentType.JSON)
        .header("Authorization", "Token " + token)
        .when()
        .post("/articles/" + slug + "/favorite")
        .then()
        .statusCode(200)
        .body("article.slug", equalTo(slug))
        .body("article.favorited", is(true))
        .body("article.favoritesCount", equalTo(1));
  }
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
