  }
protected String registerAndGetToken(String email, String username, String password){
    return given()
        .contentType(ContentType.JSON)
        .body(Map.of("user", Map.of("email", email, "username", username, "password", password)))
        .when()
        .post("/users")
        .then()
        .statusCode(201)
        .extract()
        .path("user.token");
  }
protected String createArticleAndGetSlug(String token, String title, String description, String body, List<String> tags){
    Map<String, Object> article = new HashMap<>();
    article.put("title", title);
    article.put("description", description);
    article.put("body", body);
    article.put("tagList", tags);

    return given()
        .contentType(ContentType.JSON)
        .header("Authorization", "Token " + token)
        .body(Map.of("article", article))
        .when()
        .post("/articles")
        .then()
        .statusCode(200)
        .extract()
        .path("article.slug");
  }
